mapper.select:
select so.id as id, so.serial_number as serialNumber, so.supplier_id as 'supplier.id', sup.name as 'supplier.name', a.measure_mode as measureMode, so.product_type, a.category, a.quantity, a.actualQuantity, CASE WHEN a.product_type = 2 THEN a.mete / 1000 WHEN a.product_type = 4 and a.measure_mode = 1 THEN a.mete / 1000 WHEN a.product_type = 4 and a.measure_mode = 2 THEN a.totalArea / 1000000 ELSE 0 END AS mete, CASE WHEN a.product_type = 2 THEN a.actualMete / 1000 WHEN a.product_type = 4 and a.measure_mode = 1 THEN a.actualMete / 1000 WHEN a.product_type = 4 and a.measure_mode = 2 THEN a.actualtotalArea / 1000000 ELSE 0 END AS actualMete from project_labor_subsupplier_order so INNER JOIN ( SELECT supplier_order_id, product_type, category, measure_mode, sum(quantity) as quantity, sum(actual_quantity) as actualQuantity, sum(mete) as mete, sum(actual_mete) as actualMete, sum(total_area) as totalArea, sum(actual_total_area) as actualtotalArea FROM project_labor_subsupplier_order_product_link where bool_delete_enum = 0
AND project_id = #{projectId}
group by supplier_order_id, product_type, category, measure_mode )a on a.supplier_order_id = so.id left join scm_supplier sup on sup.id = so.supplier_id and sup.bool_delete_enum = 0 where so.bool_delete_enum = 0
AND so.project_id = #{projectId}
